mapper.delete:
DELETE FROM LEARNING_OBSERVATIONS
WHERE ID = #{id}
	AND LESSON_REPORT_ID = #{lessonReportId}
	AND LESSON_REPORT_ID IN (
		SELECT R.ID
		FROM LESSON_REPORTS R
		INNER JOIN LESSONS L
			ON R.LESSON_ID = L.ID
		INNER JOIN STUDENTS S
			ON L.STUDENT_ID = S.ID
		WHERE S.INSTRUCTOR_ID = #{instructorId}
	)
